import { Dimensions, StyleSheet } from 'react-native';

const useResponsiveLayout = () => {
  const [screenData, setScreenData] = useState(Dimensions.get('window'));

  useEffect(() => {
    const subscription = Dimensions.addEventListener('change', ({ window }) => {
      setScreenData(window);
    });

    return () => subscription.remove();
  }, []);

  const styles = StyleSheet.create({
    container: {
      padding: screenData.width > 768 ? 24 : 16,
      maxWidth: screenData.width > 768 ? 768 : '100%'
    },
    text: {
      fontSize: screenData.width > 768 ? 18 : 16
    }
  });

  return { styles, screenData };
};


interface SyncAction {
  id: string;
  type: 'create' | 'update' | 'delete';
  data: any;
  timestamp: number;
}

interface ConflictResolution {
  resolve: (local: any, remote: any) => any;
  strategy: 'client_wins' | 'server_wins' | 'merge' | 'manual';
}

class OfflineDataManager {
  private queue: SyncAction[] = [];
  private isProcessing = false;

  addAction = (action: SyncAction): void => {
    this.queue.push({ ...action, timestamp: Date.now() });
    this.processQueue();
  };

  processQueue = async (): Promise<void> => {
    if (this.isProcessing) return;

    this.isProcessing = true;

    while (this.queue.length > 0) {
      const action = this.queue.shift();

      try {
        await this.executeAction(action);
      } catch (error) {
        console.error('Sync action failed:', error);
        // Add to retry queue or handle error
      }
    }

    this.isProcessing = false;
  };

  private executeAction = async (action: SyncAction): Promise<void> => {
    switch (action.type) {
      case 'create':
        await this.createItem(action.data);
        break;
      case 'update':
        await this.updateItem(action.data);
        break;
      case 'delete':
        await this.deleteItem(action.data);
        break;
    }
  };

  // Conflict resolution methods
  resolveConflicts = async (localItems: any[], remoteItems: any[]): Promise<any[]> => {
    // Implement conflict resolution strategy
    return this.mergeStrategy(localItems, remoteItems);
  };
}


